// Generated by scripts/gen-skills.mjs from skills/**/*.md (D-105). Do not edit.
export const skills = {
  "accord/SKILL.md": "---\nname: accord\ndescription: Use when starting any work in an accord repository, when seeing where work stands, or when continuing a ticket. Shows the dashboard, continues or picks up a ticket, and classifies a new request into a lane.\nlicense: MIT\nkind: skill\n---\n\n`/accord` is the entry point. It routes to the stage skills, so nobody has to\nremember their names.\n\n## Dashboard: `/accord` with no argument\n\n1. Run `accord status --json`, and `accord next --json` for the tickets ready\n   to pick up. Read the name to greet from `git config user.name`, and your\n   email from `git config user.email`.\n2. Show the dashboard built from that JSON. You format it; you never infer a\n   state the JSON does not hold.\n\n   ```\n   Hello <name>\n\n   YOURS IN PROGRESS\n     T-12  Login API          build 3/5\n\n   TEAM\n     T-15  Session store      done\n     T-19  Export CSV         in progress · binh\n     T-18  Login UI           blocked by T-12\n\n   READY TO PICK UP\n     T-21  Password reset     M\n\n   → [Continue T-12]  [Pick up T-21]  [New request]\n   ```\n\n   Yours are the tickets whose `claimedBy` is your `user.email`, each with\n   its `stage` and tasks (`tasksDone`/`tasksTotal`). The ones to pick up are\n   those `accord next` lists. The team's are the rest, other than those\n   `accord next` lists, with who holds them and their `blockedBy`.\n3. Offer Continue, Pick up, and New request.\n\n## Continue\n\n1. Switch to branch `t/<id>`. The active ticket is the branch, read from git,\n   never from memory.\n2. Run `accord anchor`. It prints the stage and the position from the ledger,\n   then the owner's words verbatim.\n3. Load the stage skill for the stage it prints: `intent` → `accord-intent`,\n   `plan` → `accord-plan`, `build` → `accord-build`, `review` →\n   `accord-review`, `verify` → `accord-verify`. Resume at the step the anchor\n   names. Never re-run a task the ledger records.\n\n## Pick up\n\nCreate branch `t/<id>` and push it: the pushed branch is the claim. Then\ncontinue as above.\n\n## New request: `/accord <request>`\n\nPropose a lane with its reason, out loud. The owner may override.\n\n| Lane | Example |\n|---|---|\n| S: small fix | bug, copy change, one flag |\n| M: feature | one story |\n| L: epic | 3 to 10 related stories |\n| P: project | greenfield |\n\nAny of these lifts S to M: new user-visible behaviour; a public interface or\nschema changes; auth, money, or data deletion is touched; more than one\nplausible reading; more than about three files expected.\n\n- **S.** Write back two lines in chat, `Understood: …` and `Done when: …`.\n  Proceed without waiting only when the request has a concrete anchor (file,\n  symbol, error message, or expected behaviour) and one plausible reading;\n  otherwise ask exactly one question and wait. Do the change in the main\n  session, run the affected tests, have one reviewer pass in a fresh context,\n  and give a short report in chat.\n- **M.** Run `accord new ticket <id> --lane M`, create branch `t/<id>`, then\n  load `accord-intent`.\n- **L and P.** Not built yet. Say so, and propose splitting the work into\n  lane M tickets linked by `depends_on`.\n\n## Rules\n\n- A lane only rises. Complexity found mid-task lifts the lane: stop, say so,\n  and re-enter at the new lane's first incomplete stage. A lane never drops.\n- A ticket without `lane:` follows the 0.1.0 contract. Offer to add `lane: M`\n  and the lane headings; do it only on a yes.\n- In lane M the main session orchestrates and never edits product code.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision on a\n  ticket is a Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`.\n",
  "approach/SKILL.md": "---\nname: accord-approach\ndescription: Use when a lane M ticket has its intent and acceptance criteria and needs an approach. Chooses the lightest approach that works, has a critic argue against it, and takes the owner's explicit yes before accord approve.\nlicense: MIT\nkind: skill\n---\n\nThis stage chooses how the ticket will be built, lightest first, and takes\nthe owner's yes before anyone plans. You run it in the main session.\n\n## Steps\n\n1. Run `accord anchor`.\n\n2. **Options.** Dispatch `accord-architect` with the path of\n   `accord/tickets/<id>.md`. It runs an impact analysis (callers,\n   interfaces, tests, config, exports the change must reach) and proposes\n   two or three options in ladder order. The first option is always the\n   lightest that works. Every added layer of complexity names the\n   acceptance criterion or constraint that requires it, or is dropped.\n\n3. **Critique.** The chosen option is the one the architect marks\n   `Recommended`, unless the owner has already picked another. Dispatch\n   `accord-critic` in a fresh context, mode `approach`, with the path of\n   the ticket file and the chosen option's text only (its name and what it\n   does), never the architect's reasoning, risk line, or `Recommended`\n   line, so its review stays independent. It argues the strongest case\n   against the chosen option and checks it against Vetoes, Decisions, and\n   Corrections. This runs for every ticket in lane M and above.\n   If a Must finding would break a Veto, Decision, or Correction, that\n   option is out: take the first option in the architect's ladder order\n   that is not yet ruled out, and run the critic again on it. If no option\n   is left, ask the owner. When the ticket touches auth, money, migration,\n   or data deletion, ask the critic for three concrete failure scenarios as\n   well.\n\n4. **Write `## Approach`** in `accord/tickets/<id>.md`, about fifteen lines:\n\n   - chosen option and why;\n   - rejected options and why;\n   - affected areas;\n   - risks: every critic finding the chosen option keeps, Must findings\n     first, so the owner approves with them in view; for a ticket that\n     touches auth, money, migration, or data deletion, each of the\n     critic's three failure scenarios and how it is undone;\n   - test strategy: which criterion is tested at which layer.\n\n5. **The owner's yes.** Show the owner the brief and ask for an explicit\n   yes. On yes, run `accord approve <id>`, then `accord gate ready <id>`\n   and work from what it prints. If the owner picks another option, go\n   back to step 3 with that option, rewrite the brief, and ask again.\n   `accord approve` runs only on a yes to the brief as shown. Never run\n   `accord approve` without the owner's yes in this conversation.\n\n6. Next: `accord-plan`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- A later change to Intent, acceptance criteria, Vetoes, Decisions,\n  Corrections, or Approach needs a new yes from the owner and a new\n  `accord approve <id>`.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n",
  "build/SKILL.md": "---\nname: accord-build\ndescription: Use when a lane M ticket has a plan that passed accord gate plan and needs building. Dispatches one fresh executor per task from accord brief, runs the affected tests itself, and records each task with accord task-done.\nlicense: MIT\nkind: skill\n---\n\nThis stage builds the plan one task at a time. You run it in the main\nsession and orchestrate: executors write the code.\n\n## Steps\n\n1. Run `accord anchor`. It names the next task.\n\n2. **Dispatch.** For each task in `plan.md` without a line in\n   `accord/tickets/<id>/ledger.md`, in order, one at a time: run\n   `accord brief <id> <n>` into a file and dispatch a fresh\n   `accord-executor` with the path of that file only. Never pass chat\n   history.\n\n3. **Record.** When it reports, run the affected tests yourself: the\n   `tests.affected` command from `accord/config.yml`, with `{files}`\n   replaced by the paths on the task's `files:` line. Then run\n   `accord task-done <id> <n>` and work from what it prints. The\n   executor's claim alone records nothing.\n\n4. **Blocked.**\n   - `BLOCKED` with a question that touches intent, a veto, a criterion,\n     or a public interface: ask the owner.\n   - `BLOCKED` on a test that seems wrong: a criterion test is the\n     owner's, so ask the owner; any other test is a plan gap and goes back\n     to `accord-plan`. Never edit the test yourself.\n   - `BLOCKED: context`: dispatch a fresh executor with the same brief\n     plus the diff and the ledger so far.\n   - `NEEDS_CONTEXT`: answer, and dispatch again.\n\n5. **Files.** A file outside the task's `files:` line must be declared\n   in the report with a reason. When you accept it, record a Ruling.\n\n6. **Change of course.** When the approved approach cannot work, stop.\n   Write a change note under the ticket's `## Approach`: what failed,\n   which finished tasks still hold, and the proposed new approach. Ask the\n   owner for a new yes; on yes run `accord approve <id>`, then\n   `accord-plan` re-plans only the tasks the change touches. Never\n   re-plan quietly.\n\n7. **Plan changed.** When `accord task-done` says `plan.md` changed,\n   never run `accord gate plan` to clear it. Show the owner the diff of\n   `plan.md`. If the owner made the change, `accord-plan` reviews it\n   (critic, then `accord gate plan`); otherwise restore `plan.md` with the\n   owner's yes and dispatch again. Only `accord-plan` changes the plan.\n\n8. When every task has a ledger line, next: `accord-review`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary:\n  the executor gets it inside its brief.\n- The main session orchestrates and never edits product code.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n",
  "designer/SKILL.md": "---\nname: accord-designer\ndescription: Use when a ticket is marked ui and the Ready gate is asking for a design reference. Establishes whether the ticket has an interface, picks a design link or a prototype from the profile, produces the missing one, and re-runs the gate.\nlicense: MIT\nkind: role\nloads: [shared/prototype.md]\n---\n\nDesigner is a stage a ticket passes through, not a job title. The same person\nand agent move through intent, design, and implementation in turn. This stage\nends when the ticket carries the design reference the gate was asking for.\n\n## Steps\n\n1. Run `accord gate ready <id>` and read the reasons it prints. Those reasons\n   are the whole brief for this stage. If none of them is about design, there\n   is nothing to do here — hand the ticket back to the stage that owns the\n   reason rather than inventing work.\n\n2. Read `ui:` in the frontmatter of `accord/tickets/<id>.md`.\n\n   - `ui: false` — stop. A ticket with no interface has no design reference to\n     produce.\n   - `ui: true` — continue.\n\n3. Read `profile:` in `accord/config.yml` and take the matching branch.\n\n   - `profile: build` — the ticket needs a design link or a prototype. When\n     the design already exists, put its link in `design:` in the ticket\n     frontmatter. When it does not, read `./prototype.md` and build one.\n   - `profile: maintain` — the ticket needs\n     `accord/assets/<id>/prototype.html`. Read `./prototype.md` and build it\n     from the styles the project already has. A prototype invented from new\n     styles is a redesign nobody asked for.\n\n4. Run `accord gate ready <id>` again. The reason you came here for is gone,\n   or the work is not finished.\n\n## Boundaries\n\nYou own the design reference and nothing else. Acceptance criteria belong to\nthe stage that wrote them: a scenario you disagree with goes to\n`## Open questions` in the ticket, never into an edit of\n`## Acceptance criteria`.\n",
  "intent/SKILL.md": "---\nname: accord-intent\ndescription: Use when a lane M ticket needs its intent captured, or when /accord routes a new request here. Runs the intent interview that writes the ticket's Intent, acceptance criteria, Vetoes, Decisions, and Corrections, so later stages cannot drift from what the owner meant.\nlicense: MIT\nkind: skill\n---\n\nThis stage writes down what the owner means, in the ticket, before anyone\nplans or builds. You run it in the main session.\n\n## Steps\n\n1. Run `accord anchor`. If the ticket file does not exist yet, `/accord`\n   creates it first: start there.\n\n2. **Look before asking.** Dispatch `accord-scout` with the path of\n   `accord/tickets/<id>.md` and the questions the code can answer. Never ask\n   the owner what the code answers. A question about an existing project\n   cites the file that prompted it.\n\n3. **Confirm the parts.** Before the first score, list the request's\n   top-level parts and ask the owner to confirm them.\n\n4. **Score ambiguity** from 0 to 1 on four dimensions: goal, scope boundary,\n   constraints, acceptance; 0 is unambiguous, 1 is unknown. Show the owner\n   the four scores after each round. No dimension may stay above 0.4. Stop\n   when the total (the mean) is 0.2 or less with no dimension above 0.4, or\n   when the owner says \"enough\".\n   Before you stop, ask once for the smallest version that still counts as\n   done.\n   On \"enough\", write `Ruling: interview stopped by the owner at <score>`\n   into `accord/tickets/<id>/ledger.md` under `## Rulings`.\n\n5. **One question per message**, aimed at the dimension with the highest\n   score. Multiple\n   choice where possible, the recommended option first with its reason.\n\n6. **Write the ticket** `accord/tickets/<id>.md`, each section as follows:\n\n   | Section | Content |\n   |---|---|\n   | `## Intent` | at most five lines: why, for whom, success measure, non-goals; you draft, the owner approves |\n   | `## Acceptance criteria` | two to five Gherkin scenarios, `@ac-1` … `@ac-n`; you draft, the owner approves |\n   | `## Vetoes` | what the owner forbids, in the owner's words |\n   | `## Decisions` | settled answers in the owner's words: `- D-01 <decision> — \"<the owner's sentence>\"` |\n   | `## Corrections` | every \"no, I meant…\", verbatim, append-only, written before any other action |\n   | `## Open questions` | each unanswered question as an unchecked `- [ ]` item |\n\n7. **Write back** your understanding. Separate what the owner said from what\n   you assumed, and invite correction.\n\n8. **Audit once.** Dispatch `accord-auditor` with only the path of the\n   ticket file. A criterion it reads two ways goes back to the owner as a\n   question.\n\n9. Next: `accord-approach`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- A correction goes into `## Corrections` verbatim before any other action.\n  A correction that exists only in the conversation is lost at the next\n  compaction.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n",
  "plan/SKILL.md": "---\nname: accord-plan\ndescription: Use when a lane M ticket has an approved approach and needs a plan. Has the planner write plan.md task by task, checks it with accord gate plan and the critic, and runs the full test suite on the baseline before build.\nlicense: MIT\nkind: skill\n---\n\nThis stage turns the approved approach into tasks an executor can finish\none at a time. You run it in the main session. The owner does not need to\nread the plan.\n\n## Steps\n\n1. Run `accord anchor`.\n\n2. **Plan.** Run `git rev-parse HEAD`, read `review.mode` in\n   `accord/config.yml` (absent counts as `human`), and dispatch\n   `accord-planner` with the path of `accord/tickets/<id>.md`, that commit,\n   and the mode. It writes `accord/tickets/<id>/plan.md` with frontmatter\n   `baseline: <git rev-parse HEAD>` and one `## Task <n>: <title>` section\n   per task. Each task carries a `covers:` line, a `files:` line, and a\n   `verify:` line, then prose for the executor: the interface (consumes,\n   produces) and the test written first. A task fits in about half an\n   executor's context; the planner splits anything larger.\n\n3. **Slices.** Under `review: human` the planner groups tasks into slices:\n   each slice is one pull request covering a stated subset of the\n   acceptance criteria, green on its own. The planner writes each slice\n   into `plan.md`: the tasks it holds and the criteria it covers. Under\n   `review: outcome` it is one branch, no slices.\n\n4. **Gate.** Run `accord gate plan <id>` and fix what it prints, then run\n   it again until it passes. On a pass it writes `plan_hash:` into\n   `plan.md`. A plan changed after that, by a critic round or anything\n   else, must pass `accord gate plan <id>` again before `accord task-done`\n   records a task, so re-run the gate after every revision. A gate\n   failure you cannot fix counts as an open finding in step 6.\n\n5. **Critique.** Dispatch `accord-critic` in a fresh context, mode `plan`,\n   with the path of the ticket file and the path of `plan.md`. After each\n   critic round, commit `plan.md` with the subject\n   `plan: <id> round <n>, <m> Must, <s> Should`. When the critic reports\n   no Must or Should, go to step 7. Otherwise have the planner fix every\n   Must and every Should, then go back to step 4.\n\n6. **Rounds.** At most three revision rounds. If Must or Should findings\n   are still open after the third, stop and tell the owner what is still\n   open, and show the revision with the fewest Must findings: its round\n   and its commit, read from `git log`. Never continue on\n   a failing plan.\n\n7. **Baseline tests.** Before the first build commit, run the\n   `tests.full` command from `accord/config.yml` at the current HEAD, and\n   only while `git diff --stat <baseline> HEAD` shows no change outside\n   `accord/`. Never check out, stash, reset, or clean to reach the\n   baseline. If product code has changed since the baseline, ask the\n   owner. Show the owner every failing case; the owner decides whether it\n   is fixed first or tracked as its own ticket. Never ignore a failing\n   case on your own.\n\n8. Next: `accord-build`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n",
  "shared/prototype.md": "---\nkind: reference\n---\n\n# Producing a prototype\n\nA `ui: true` ticket needs something a reviewer can look at before the code\nexists. In the `maintain` profile that something is\n`accord/assets/<id>/prototype.html`, and it is derived from what the project\nalready looks like — not from a fresh idea of what it could look like.\n\n## 1. Find the styles the project already has\n\nBefore writing any markup, find where the look of this project is defined.\nLook for, in roughly this order:\n\n- the path named under `design.tokens` in `accord/config.yml`, if one is set;\n- a stylesheet or variables file the application loads on every page;\n- a utility-class configuration, if the project styles that way;\n- a components or design-system folder.\n\nRead what you find. You are looking for the names the project uses for its\ncolours, spacing, radii, and type — those names are what the prototype spends,\nand inventing new ones is a redesign the ticket did not ask for.\n\nIf you find nothing, say so in the ticket's `## Open questions` and keep\ngoing: a prototype built from nothing has to record what it was built from\ninstead.\n\n## 2. Start from a single HTML file\n\nOne HTML file: a comment block at the top, an empty body. The comment block\nnames the ticket, a `Derived from:` line for what step 1 found, and the owner.\nBuild the page underneath it. One file, no build step, no assets directory —\na reviewer opens it in a browser and it works.\n\n## 3. Put it where the gate looks\n\n`accord/assets/<id>/prototype.html`, with `<id>` the ticket id. That folder is\nthis stage's own; nothing else writes into it.\n\n## 4. Run `accord lint` and fix what it reports\n\nDo not work from memory of the rules — run it, read the reasons, and fix what\nit names.\n\nA finding you disagree with is a question, not a licence: write it into the\nticket's `## Open questions` and stop, rather than working around the rule.\n\n## 5. Re-run the gate\n\n`accord gate ready <id>` is the only thing that says whether the ticket now\nhas what it was missing.\n",
} as const;
export type SkillKey = keyof typeof skills;
